CREATE OR REPLACE VIEW mc.v_host_connection_status (host_id, status, live_status, ticket_id) AS SELECT
host.id host_id,
(CASE WHEN host.active = 0 THEN 0 ELSE
(CASE WHEN ((cio.down_date IS NOT NULL AND cio.down_date::text <> '')
AND ((statement_timestamp() - cio.down_date) * 24 * 60) > host.escalation_timeout)
THEN coalesce(cio.type_id, -1)
ELSE -1 END) END) status,
(CASE WHEN host.active = 0 THEN 0 ELSE coalesce(cio.type_id, -1) END) live_status,
(CASE WHEN coalesce(cio.event_id::text, '') = ''
THEN NULL ELSE (SELECT ticket_id FROM tt.event e WHERE e.id = cio.event_id) END) ticket_id
FROM mss.host, host
LEFT OUTER JOIN mc.connection_interrupt_open cio ON (host.id = cio.host_id);

