CREATE OR REPLACE VIEW bireader.v_mc_portal_role (id, login_id, user_role, user_role_desc, user_role_scope, user_role_scope_desc, is_internal) AS SELECT
    r2p.id          as id,
    l2p.login_id    as login_id,
    r.name          as user_role,
    r.description   as user_role_desc,
    s.name          as user_role_scope,
    s.description   as user_role_scope_desc,
    r.is_internal   as is_internal
