CREATE OR REPLACE VIEW mc.connection_interrupt (id, down_date, up_date, type_id, minutes, details, event_id, host_id, interrupt_review_status_id) AS SELECT id, down_date, (CASE WHEN up_date < down_date THEN down_date ELSE up_date END) up_date, type_id,
         CAST((CASE WHEN up_date < down_date THEN 0 ELSE minutes END) as numeric(22)) minutes, details, event_id, host_id, INTERRUPT_REVIEW_STATUS_ID
    FROM mc.connection_interrupt_closed

UNION ALL

  SELECT id, down_date, up_date, type_id,
         CAST((CASE WHEN coalesce(up_date::text, '') = '' THEN TRUNC((statement_timestamp()-down_date) * 60 * 24) END) as numeric(22)) minutes, details, event_id, host_id, INTERRUPT_REVIEW_STATUS_ID
    FROM mc.connection_interrupt_open;

