CREATE OR REPLACE VIEW mss.time_zone (id, short, utc_offset, name, dst) AS SELECT td.id, td.short,
(CASE
  WHEN(statement_timestamp() AT TIME ZONE 'UTC') > td.dst_start_utc AND (statement_timestamp() AT TIME ZONE 'UTC') < td.dst_end_utc
  THEN td.utc_offset_dst/60000
  ELSE td.utc_offset_std/60000
 END),
td.name,
(CASE
  WHEN(statement_timestamp() AT TIME ZONE 'UTC') > td.dst_start_utc AND (statement_timestamp() AT TIME ZONE 'UTC') < td.dst_end_utc
  THEN 1
  ELSE 0
END)
FROM mss.time_zone_data td;

