CREATE OR REPLACE VIEW bireader.v_mss_installation_project_item (id, name, installation_project_id, customer_contact_id, osag_contact_id, original_completion_date, estimated_completion_date, completion_date, order_date, config_received_date, shipment_date, shipment_arrived_date, activated_date, cancellation_date, ticket_id, blueprint_id, delayed, delay_reason, delay_date, shipment_est_arrived_date, processed_date, latest_dispatch_date, order_contact_id, approval_contact_id, creation_date) AS SELECT ID, NAME, INSTALLATION_PROJECT_ID, CUSTOMER_CONTACT_ID, OSAG_CONTACT_ID, CAST((ORIGINAL_COMPLETION_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as ORIGINAL_COMPLETION_DATE,
CAST((ESTIMATED_COMPLETION_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as ESTIMATED_COMPLETION_DATE, 
CAST((COMPLETION_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as COMPLETION_DATE, 
CAST((ORDER_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as ORDER_DATE, 
CAST((CONFIG_RECEIVED_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as CONFIG_RECEIVED_DATE, CAST((SHIPMENT_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as SHIPMENT_DATE,CAST((SHIPMENT_ARRIVED_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as SHIPMENT_ARRIVED_DATE, 
CAST((ACTIVATED_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as ACTIVATED_DATE, CAST((CANCELLATION_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as CANCELLATION_DATE, TICKET_ID, BLUEPRINT_ID, DELAYED, DELAY_REASON, CAST((DELAY_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as DELAY_DATE, CAST((SHIPMENT_EST_ARRIVED_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as SHIPMENT_EST_ARRIVED_DATE,
CAST((PROCESSED_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as PROCESSED_DATE, CAST((LATEST_DISPATCH_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as LATEST_DISPATCH_DATE, ORDER_CONTACT_ID, APPROVAL_CONTACT_ID, CAST((CREATION_DATE AT TIME ZONE 'UTC') as TIMESTAMP)  as CREATION_DATE  FROM MSS.INSTALLATION_PROJECT_ITEM;

CREATE OR REPLACE VIEW bireader.v_vpn_tunnel (id, ospf_cost, status, tunnelmode, active, compression, egress_bw, ingress_bw, last_event_id, latency, status_date, member_no, vpn_member_id1, vpn_member_id2, ipv6_tunnel, octets_per_second_in, octets_per_second_out, rtt, loss) AS SELECT ID, OSPF_COST, STATUS, TUNNELMODE, ACTIVE, COMPRESSION, EGRESS_BW, INGRESS_BW, LAST_EVENT_ID, LATENCY, STATUS_DATE, MEMBER_NO, VPN_MEMBER_ID1, VPN_MEMBER_ID2, IPV6_TUNNEL, OCTETS_PER_SECOND_IN, OCTETS_PER_SECOND_OUT, RTT, LOSS FROM VPN.TUNNEL;

CREATE OR REPLACE VIEW bireader.v_auth_login2groups (login_id, name) AS Select l2tg.login_id, tg.name

FROM AUTH.PASSPORT_LOGIN2TUNNELGROUP l2tg
         JOIN AUTH.TUNNELGROUP tg on (l2tg.TUNNELGROUP_id = tg.id)
         JOIN AUTH.PASSPORT_LOGIN l ON l2tg.login_id=l.id
         JOIN STOP.PASSPORT_CONTACT c ON l.contact_id=c.id
WHERE c.company_id=6;

CREATE OR REPLACE VIEW bireader.v_auth_tunnelgroup (id, name, authsys_id, description) AS SELECT ID,NAME,AUTHSYS_ID,DESCRIPTION FROM AUTH.TUNNELGROUP;

CREATE OR REPLACE VIEW bireader.v_mc_permission_radius (login_id, radiusgroup_id, radiusgroup_name, radiusgroup_description) AS SELECT    l.id  as login_id,    g.id as radiusgroup_id,    g.name  as radiusgroup_name,    g.description as radiusgroup_description
FROM AUTH.PASSPORT_LOGIN2GROUPS l2g
         JOIN AUTH.PASSPORT_LOGIN l on (l2g.LOGIN_ID=l.id)
         JOIN AUTH.GROUPS  g on (l2g.GROUP_ID = g.id)
         JOIN STOP.PASSPORT_CONTACT c ON (c.id = l.contact_id)
WHERE c.company_id=6;

CREATE OR REPLACE VIEW bireader.v_auth_login2tunnelgroup (id, radiusgroup_name, radiusgroup_description) AS select l.id,
       g.name          as radiusgroup_name,
       g.description   as radiusgroup_description
FROM AUTH.PASSPORT_LOGIN2GROUPS l2g
         JOIN AUTH.PASSPORT_LOGIN          l on (l2g.LOGIN_ID=l.id)
         JOIN AUTH.GROUPS         g on (l2g.GROUP_ID = g.id)
         JOIN STOP.PASSPORT_CONTACT        c ON (c.id = l.contact_id)
WHERE c.company_id=6;

CREATE OR REPLACE VIEW bireader.v_mss_network (id, version, name, ip_address, netmask, scope_company_id, author, comments, description) AS Select ID, VERSION, NAME, IP_ADDRESS, NETMASK, SCOPE_COMPANY_ID, AUTHOR, COMMENTS, DESCRIPTION FROM MSS.NETWORK;

CREATE OR REPLACE VIEW osixinfo.v_firmwarebase (id, firmware_base, hardware_id, change_timestamp) AS SELECT
  id,
  value as firmware_base,
  hardware_id as hardware_id,
  change_timestamp as change_timestamp
