  change_timestamp as change_timestamp
FROM osixinfo.osixinfo
WHERE key='hostClusterState';

CREATE OR REPLACE VIEW osixinfo.v_image (id, image, hardware_id, change_timestamp) AS SELECT
  id,
  value as image,
  hardware_id as hardware_id,
  change_timestamp as change_timestamp
FROM osixinfo.osixinfo
WHERE key='image';

CREATE OR REPLACE VIEW osixinfo.v_firmware (id, firmware, hardware_id, change_timestamp) AS SELECT
  id,
  value as firmware,
  hardware_id as hardware_id,
  change_timestamp as change_timestamp
FROM osixinfo.osixinfo
WHERE key='firmware';

CREATE OR REPLACE VIEW osixinfo.v_last_update (id, last_update, hardware_id, change_timestamp) AS SELECT
  osixinfo.id,
  osixinfo.change_timestamp last_update,
  osixinfo.hardware_id hardware_id,
  osixinfo.change_timestamp change_timestamp
FROM osixinfo.osixinfo
WHERE osixinfo.key='last_update';

CREATE OR REPLACE VIEW osixinfo.v_mac (id, mac, hardware_id, change_timestamp) AS SELECT
    id,
    osixinfo.value mac,
    osixinfo.hardware_id hardware_id,
    osixinfo.change_timestamp change_timestamp
FROM osixinfo.osixinfo
WHERE osixinfo.key='hardware';

