CREATE OR REPLACE VIEW bireader.v_mss_static_route (id, ospf_dont_propagate_route, network_id, nexthop_interface_id, priority) AS Select  ID, OSPF_DONT_PROPAGATE_ROUTE, NETWORK_ID, NEXTHOP_INTERFACE_ID, PRIORITY FROM  MSS.STATIC_ROUTE;

CREATE OR REPLACE VIEW bireader.v_mss_hardware_deploy_reason (id, name, description) AS SELECT ID, NAME, DESCRIPTION FROM MSS.HARDWARE_DEPLOY_REASON;

CREATE OR REPLACE VIEW mss.v_host_key_value (host_id, key_name, scope, object_id, string_value) AS select distinct v.host_id,
       v.key_name as key_name,
       CASE WHEN v.n_scope=1 THEN  'host' WHEN v.n_scope=2 THEN  'service' WHEN v.n_scope=3 THEN  'group' WHEN v.n_scope=4 THEN  'vpn' WHEN v.n_scope=5 THEN  'company'  ELSE 'default' END  as scope,
       v.object_id,
       v.string_value
FROM (select v.*,
      min(v.n_scope) over (partition by v.HOST_ID, v.key_name) as min_scope
    from mss.mv_value_host_default v) v
where v.min_scope = v.n_scope;


